# Let me try a more efficient approach using local search with fast cycle detection
import random
import itertools
from collections import deque, defaultdict

n = 24

def count_short_cycles(adj):
    """Count triangles, 4-cycles, and 5-cycles."""
    triangles = 0
    four_cycles = 0
    five_cycles = 0

    # Triangles: check all triples
    for i in range(n):
        for j in adj[i]:
            if j <= i:
                continue
            for k in adj[j]:
                if k <= j:
                    continue
                if k in adj[i]:
                    triangles += 1

    # 4-cycles: for each pair (i,j) with i<j, count common neighbors
    for i in range(n):
        for j in range(i+1, n):
            common = len(adj[i] & adj[j])
            if common >= 2:
                four_cycles += common * (common - 1) // 2

    # 5-cycles: BFS from each vertex, count paths of length 4 that form cycles
    # A 5-cycle is a sequence v0-v1-v2-v3-v4-v0 with all distinct
    # We'll count each cycle 10 times (5 choices of starting vertex * 2 directions)
    for v0 in range(n):
        for v1 in adj[v0]:
            if v1 < v0:
                continue
            for v2 in adj[v1]:
                if v2 == v0 or v2 < v0:
                    continue
                for v3 in adj[v2]:
                    if v3 == v1 or v3 == v0 or v3 < v0:
                        continue
                    for v4 in adj[v3]:
                        if v4 == v2 or v4 == v1 or v4 < v0:
                            continue
                        if v4 in adj[v0] and v4 != v3:
                            five_cycles += 1

    return triangles, four_cycles, five_cycles

def get_degrees(adj):
    return [len(adj[i]) for i in range(n)]

def random_initial_graph():
    """Create a random graph with degrees 4 or 5."""
    adj = [set() for _ in range(n)]

    # Target degrees: try all 4s first, then some 5s
    target = [4] * n
    # Make some vertices degree 5
    for i in random.sample(range(n), 8):
        target[i] = 5

    # Randomly add edges to meet targets
    edges = set()
    for i in range(n):
        while len(adj[i]) < target[i]:
            candidates = [j for j in range(n) if j != i and len(adj[j]) < target[j] and (min(i,j), max(i,j)) not in edges]
            if not candidates:
                break
            j = random.choice(candidates)
            edges.add((min(i,j), max(i,j)))
            adj[i].add(j)
            adj[j].add(i)

    return adj, edges

def try_swap(adj, edges):
    """Try a random edge swap. Remove (a,b) and (c,d), add (a,c) and (b,d)."""
    edge_list = list(edges)
    if len(edge_list) < 2:
        return None, None

    for _ in range(100):
        e1 = random.choice(edge_list)
        e2 = random.choice(edge_list)
        if e1 == e2:
            continue

        a, b = e1
        c, d = e2

        # Need 4 distinct vertices
        if len({a, b, c, d}) != 4:
            continue

        # New edges
        ne1 = (min(a, c), max(a, c))
        ne2 = (min(b, d), max(b, d))

        if ne1 in edges or ne2 in edges:
            continue

        # Perform swap
        new_edges = set(edges)
        new_edges.remove(e1)
        new_edges.remove(e2)
        new_edges.add(ne1)
        new_edges.add(ne2)

        new_adj = [set() for _ in range(n)]
        for u, v in new_edges:
            new_adj[u].add(v)
            new_adj[v].add(u)

        return new_adj, new_edges

    return None, None

# Main local search
random.seed(123)
best_adj = None
best_score = float('inf')
best_edges = None

for restart in range(20):
    adj, edges = random_initial_graph()

    # Check if initial graph has valid degrees
    degs = get_degrees(adj)
    if not all(4 <= d <= 5 for d in degs):
        continue

    t, f, fi = count_short_cycles(adj)
    score = t + f + fi

    if score < best_score:
        best_score = score
        best_adj = adj
        best_edges = edges
        print(f"Restart {restart}: initial score = {score} (t={t}, f={f}, fi={fi}), edges={len(edges)}")

    if score == 0:
        print("Found solution!")
        break

    # Local search
    no_improve = 0
    for step in range(50000):
        new_adj, new_edges = try_swap(adj, edges)
        if new_adj is None:
            continue

        new_degs = get_degrees(new_adj)
        if not all(4 <= d <= 5 for d in new_degs):
            continue

        nt, nf, nfi = count_short_cycles(new_adj)
        new_score = nt + nf + nfi

        if new_score < score or random.random() < 0.01:  # occasional acceptance of worse
            adj, edges = new_adj, new_edges
            score = new_score

            if score < best_score:
                best_score = score
                best_adj = adj
                best_edges = edges
                print(f"Restart {restart}, step {step}: new best score = {score} (t={nt}, f={nf}, fi={nfi})")

                if score == 0:
                    print("Found solution!")
                    break
            no_improve = 0
        else:
            no_improve += 1

        if no_improve > 10000:
            break

    if best_score == 0:
        break

print(f"\nFinal best score: {best_score}")
if best_score == 0:
    print("Solution found!")
    print("Degrees:", get_degrees(best_adj))
    print("Edges:", sorted(best_edges))
else:
    print("No solution found in this attempt")
    if best_adj:
        print("Best degrees:", get_degrees(best_adj))
        t, f, fi = count_short_cycles(best_adj)
        print(f"Best breakdown: t={t}, f={f}, fi={fi}")
